/*
 * MLP handwritten-digit inference for the VSDSquadron PRO (SiFive FE310-G002)
 * ===========================================================================
 * Network : 256 (16x16 pixels) -> 64 ReLU -> 32 ReLU -> 10 scores
 * Model   : mlp_model_16x16.h   generated by mlp_mnist_16x16.py (Colab)
 * Inputs  : mnist_test_16x16.h  generated by the same script
 *
 * Memory
 *   Weights, biases and test images are `static const` -> they stay in flash
 *   (.rodata). Only the small activation buffers below use the 16 KB RAM:
 *   64 + 32 bytes (uint8 activations) + 40 bytes (float scores) on the stack.
 *
 * Arithmetic (the FE310 has no FPU, so floats are done in software)
 *   For every neuron:
 *     acc   = sum_i  w_q[j][i] * x_q[i]       int8 x uint8 -> int32  (fast)
 *     real  = acc * MULT + bias[j]            1 float mul + 1 float add
 *   Hidden layers:  x_q_next[j] = clamp(round(ReLU(real) * INV_ACT), 0, 255)
 *   Output layer:   score[j] = real  -> predicted digit = argmax(score)
 *   That is ~18.8k integer MACs and only ~106 float operations per image.
 *
 * Note: newlib-nano's printf has no %f support by default, so only
 *       integers are printed.
 */

#include <stdio.h>
#include <stdint.h>

#include "mlp_model_16x16.h"
#include "mnist_test_16x16.h"

/* ---- Cycle counter (RISC-V mcycle CSR) to measure inference time ------- */
#if defined(__riscv)
static inline uint32_t read_cycles(void)
{
    uint32_t c;
    __asm__ volatile ("csrr %0, mcycle" : "=r"(c));
    return c;
}
#else
static inline uint32_t read_cycles(void) { return 0; }  /* host build */
#endif

/* ---- Hidden layer: int8 weights x uint8 inputs -> uint8 outputs --------- */
/*  w      : [n_out][n_in] int8 weights, row j = weights of neuron j          */
/*  b      : [n_out] float biases                                             */
/*  mult   : (weight scale) x (input scale), turns acc into a real value      */
/*  inv_act: 1 / (output activation scale), maps the real value to 0..255     */
static void dense_relu_u8(const uint8_t *in, int n_in,
                          const int8_t *w, const float *b, int n_out,
                          float mult, float inv_act,
                          uint8_t *out)
{
    for (int j = 0; j < n_out; ++j) {
        const int8_t *wj = w + j * n_in;        /* weights of neuron j        */
        int32_t acc = 0;
        for (int i = 0; i < n_in; ++i)
            acc += (int32_t)wj[i] * (int32_t)in[i];      /* integer MAC       */

        float real = (float)acc * mult + b[j];           /* de-quantize       */
        if (real <= 0.0f) {                              /* ReLU              */
            out[j] = 0;
        } else {
            float q = real * inv_act + 0.5f;             /* round to nearest  */
            out[j] = (q >= 255.0f) ? 255 : (uint8_t)q;   /* clamp to uint8    */
        }
    }
}

/* ---- Output layer: same MAC, but keep the real-valued scores ------------ */
static void dense_out(const uint8_t *in, int n_in,
                      const int8_t *w, const float *b, int n_out,
                      float mult, float *score)
{
    for (int j = 0; j < n_out; ++j) {
        const int8_t *wj = w + j * n_in;
        int32_t acc = 0;
        for (int i = 0; i < n_in; ++i)
            acc += (int32_t)wj[i] * (int32_t)in[i];
        score[j] = (float)acc * mult + b[j];
    }
}

/* ---- Full network: returns the predicted digit 0..9 --------------------- */
int mlp_predict(const uint8_t *pixels /* MLP_IN bytes, 0..255 */)
{
    uint8_t h1[MLP_H1];          /* layer-1 activations (64 bytes)  */
    uint8_t h2[MLP_H2];          /* layer-2 activations (32 bytes)  */
    float   score[MLP_OUT];      /* class scores        (40 bytes)  */

    dense_relu_u8(pixels, MLP_IN, &mlp_w1[0][0], mlp_b1, MLP_H1,
                  MLP_L1_MULT, MLP_L1_INV_ACT, h1);
    dense_relu_u8(h1, MLP_H1, &mlp_w2[0][0], mlp_b2, MLP_H2,
                  MLP_L2_MULT, MLP_L2_INV_ACT, h2);
    dense_out(h2, MLP_H2, &mlp_w3[0][0], mlp_b3, MLP_OUT,
              MLP_L3_MULT, score);

    int best = 0;                                /* argmax over the 10 scores */
    for (int j = 1; j < MLP_OUT; ++j)
        if (score[j] > score[best]) best = j;
    return best;
}

int main(void)
{
    int correct = 0;
    uint32_t total_cycles = 0;

    printf("MLP %dx%d digit classifier: %d-%d-%d-%d\n",
           16, 16, MLP_IN, MLP_H1, MLP_H2, MLP_OUT);

    for (int i = 0; i < NUM_TEST_IMAGES; ++i) {
        uint32_t t0 = read_cycles();
        int predicted = mlp_predict(test_images[i]);
        uint32_t dt = read_cycles() - t0;
        total_cycles += dt;

        int actual = test_labels[i];
        correct += (predicted == actual);
        printf("Image %d: Predicted = %d, Actual = %d  (%lu cycles)\n",
               i, predicted, actual, (unsigned long)dt);
    }

    printf("Accuracy: %d/%d\n", correct, NUM_TEST_IMAGES);
    printf("Average cycles per image: %lu\n",
           (unsigned long)(total_cycles / NUM_TEST_IMAGES));
    return 0;
}
